/**
 * Zone directory for the 3D/2D body (README «СПРАВОЧНИК ЗОН»). Index order MUST match the _ZONE values baked into the GLBs,
 * so it is taken from the same classifier file the build used: zones-meta.json is generated by `npm run sync` from
 * zones-core.js (= site/3d/zones.js) — keys, key index and pairs only, without the classifier code.
 */
import meta from './zones-meta.json';

const core = { KEYS: meta.keys as (string | null)[], KEY_INDEX: meta.keyIndex as Record<string, number>, ZONES: meta.zones };

/** index → zone key (`knee_l`, `chest`); index 0 = outside the 17 zones (head, front of the lower leg). */
export const ZONE_KEYS: readonly (string | null)[] = core.KEYS;
export const ZONE_COUNT = ZONE_KEYS.length; // 32 = 31 keys + "none" (index 0)
export const BASE_ZONES: readonly string[] = core.ZONES.map((z) => z.id);
export const PAIRED = new Set(core.ZONES.filter((z) => z.paired).map((z) => z.id));

export const keyToIndex = (key: string): number => core.KEY_INDEX[key] ?? 0;
export const baseOf = (key: string) => key.replace(/_(l|r)$/, '');
export const sideOf = (key: string): 'l' | 'r' | null => (/_l$/.test(key) ? 'l' : /_r$/.test(key) ? 'r' : null);

type T = (key: string, values?: Record<string, string | number>) => string;
/** Localised label from messages: body3d.zones.<base> (+ body3d.zones.left/right template). */
export function zoneLabel(t: T, key: string | null | undefined): string {
  if (!key) return t('body3d.zones.unknown');
  const zone = t(`body3d.zones.${baseOf(key)}`);
  const side = sideOf(key);
  return side ? t(side === 'l' ? 'body3d.zones.left' : 'body3d.zones.right', { zone }) : zone;
}
